class RoleType(str, Enum):
    ADMIN = "admin"
    MANAGER = "manager"

class WorkerClass(str, Enum):
    INSTALLATION_LEAD = "Instalacja prowadzący"
    INSTALLATION_WORKER = "Instalacja pracownik"
    PREFABRICATION = "Prefabrykacja"
    PREFABRICATION_LEAD = "Prefabrykacja prowadzący"
    PREFABRICATION_WORKER = "Prefabrykacja pracownik"
    FIBER_OPTICS = "Światłowody"
    OTHER = "Inne"
    OFFICE = "Biuro"
    JEDREK = "Jędrek"
    PATRYK = "Patryk"

class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True, index=True)
    email = Column(String, unique=True, index=True, nullable=False)
    hashed_password = Column(String, nullable=False)
    role = Column(String, default=RoleType.MANAGER)
    is_active = Column(Boolean, default=True)
    can_view_workers = Column(Boolean, default=True)
    can_view_projects = Column(Boolean, default=True)
    can_view_analysis = Column(Boolean, default=True)
    # NULL = wszystkie klasy (dotychczasowy dostęp); [] = brak klas do raportowania.
    allowed_worker_classes = Column(JSON(none_as_null=True), nullable=True)
    worker = relationship("Worker", back_populates="user", uselist=False, foreign_keys="Worker.user_id")

    @property
    def worker_id(self):
        return self.worker.id if self.worker else None

    @property
    def worker_name(self):
        return f"{self.worker.first_name} {self.worker.last_name}" if self.worker else None

    @property
    def worker_deleted(self):
        return bool(self.worker and self.worker.is_deleted)

    @property
    def worker_class(self):
        return self.worker.worker_class if self.worker else None

class Worker(Base):
    __tablename__ = "workers"
    id = Column(Integer, primary_key=True, index=True)
    first_name = Column(String, nullable=False)
    last_name = Column(String, nullable=False)
    worker_class = Column(String, default=WorkerClass.OTHER.value, nullable=False)
    is_active = Column(Boolean, default=True)
    is_deleted = Column(Boolean, default=False, nullable=False)
    deleted_at = Column(DateTime, nullable=True)
    email = Column(String, nullable=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True)
    can_report_hours = Column(Boolean, default=False, nullable=False)
    entries = relationship("TimeEntry", back_populates="worker")
    user = relationship("User", foreign_keys=[user_id], back_populates="worker")

    @property
    def has_login(self):
        return self.user_id is not None

class Project(Base):
    __tablename__ = "projects"
    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, nullable=False)
    category = Column(String, default=WorkerClass.INSTALLATION_WORKER.value)
    estimated_hours = Column(Float, default=0.0)
    total_m2 = Column(Float, nullable=True) 
    entries = relationship("TimeEntry", back_populates="project")
    decks = relationship("ProjectDeck", back_populates="project", cascade="all, delete-orphan", order_by="ProjectDeck.id")

class ProjectDeck(Base):
    __tablename__ = "project_decks"
    id = Column(Integer, primary_key=True, index=True)
    project_id = Column(Integer, ForeignKey("projects.id"), nullable=False, index=True)
    name = Column(String, nullable=False)
    activity = Column(String, default="", nullable=False)
    activity_names = Column("activities", JSON, nullable=True)
    conversion_factor = Column(Float, default=0.0, nullable=False)
    # Cel m² i ręcznie przydzielony plan godzin są niezależne od siebie.
    target_m2 = Column(Float, default=0.0, nullable=False)
    target_hours = Column(Float, default=0.0, nullable=False)
    is_active = Column(Boolean, default=True)

    project = relationship("Project", back_populates="decks")
    entries = relationship("TimeEntry", back_populates="deck")

    @property
    def activities(self):
        # Legacy names stay intact, including names containing commas.
        if isinstance(self.activity_names, list):
            return list(self.activity_names)
        return [self.activity] if self.activity else []

    @activities.setter
    def activities(self, names):
        self.activity_names = list(dict.fromkeys(name.strip() for name in names if name.strip()))
        self.activity = ", ".join(self.activity_names)

class JobPosition(Base):
    __tablename__ = "job_positions"
    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, nullable=False)
    is_active = Column(Boolean, default=True, nullable=False)
    entries = relationship("TimeEntry", back_populates="position")

class TimeEntry(Base):
    __tablename__ = "time_entries"
    id = Column(Integer, primary_key=True, index=True)
    worker_id = Column(Integer, ForeignKey("workers.id"))
    project_id = Column(Integer, ForeignKey("projects.id"))
    deck_id = Column(Integer, ForeignKey("project_decks.id"), nullable=True)
    position_id = Column(Integer, ForeignKey("job_positions.id"), nullable=True)
    
    is_present = Column(Boolean, default=True)
    absence_reason = Column(String, nullable=True)
    
    hours = Column(Float, nullable=True)
    m2_done = Column(Float, nullable=True)
    conversion_factor_used = Column(Float, nullable=True)
    meters_done = Column(Float, nullable=True)
    description = Column(String, nullable=True)
    
    latitude = Column(Float, nullable=True)
    longitude = Column(Float, nullable=True)
    
    date_created = Column(DateTime, default=datetime.utcnow)
    recorded_by_id = Column(Integer, ForeignKey("users.id"))

    worker = relationship("Worker", back_populates="entries")
    project = relationship("Project", back_populates="entries")
    deck = relationship("ProjectDeck", back_populates="entries")
    position = relationship("JobPosition", back_populates="entries")
    recorded_by = relationship("User")

