# ==========================================
# 4. LOGIKA BIZNESOWA I SYSTEM MAILI
# ==========================================
def verify_password(plain_password, hashed_password): return bcrypt.checkpw(plain_password.encode('utf-8'), hashed_password.encode('utf-8'))
def get_password_hash(password): return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')
def create_access_token(data: dict):
    to_encode = data.copy()
    to_encode.update({"exp": datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)})
    return jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)

def user_can_login(user: User) -> bool:
    if not user or not user.is_active:
        return False
    return not user.worker or bool(
        user.worker.is_active and not user.worker.is_deleted and user.worker.can_report_hours
    )

def worker_display_name(worker: Worker) -> str:
    name = f"{worker.first_name} {worker.last_name}"
    return f"{name} (usunięty)" if worker.is_deleted else name

def can_report_worker_class(user: User, worker: Worker) -> bool:
    return user.role == RoleType.ADMIN or user.allowed_worker_classes is None or worker.worker_class in user.allowed_worker_classes

def normalize_allowed_worker_classes(values: Optional[List[WorkerClass]]):
    return None if values is None else list(dict.fromkeys(item.value for item in values))

def get_current_user(token: str = Depends(oauth2_scheme), db: Session = Depends(get_db)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        email: str = payload.get("sub")
        if not email: raise HTTPException(status_code=401)
    except JWTError: raise HTTPException(status_code=401)
    user = db.query(User).filter(User.email == email).first()
    if not user_can_login(user): raise HTTPException(status_code=401, detail="Konto lub dostęp pracownika jest nieaktywny")
    return user

def require_admin(current_user: User = Depends(get_current_user)):
    if current_user.role != RoleType.ADMIN: raise HTTPException(status_code=403, detail="Tylko dla administratora")
    return current_user

def require_manager(current_user: User = Depends(get_current_user)):
    if current_user.role != RoleType.MANAGER: raise HTTPException(status_code=403, detail="Tylko dla prowadzącego")
    return current_user

def excel_safe(value):
    """Chroni komórki tekstowe przed wykonaniem jako formuły w Excelu."""
    if value is None:
        return ""
    value = str(value)
    return f"'{value}" if value.startswith(("=", "+", "-", "@")) else value

def calculate_meters(hours: Optional[float], conversion_factor: Optional[float]):
    """Przelicznik oznacza liczbę m² wykonywanych w ciągu jednej godziny."""
    if hours is None or conversion_factor is None or float(conversion_factor) <= 0:
        return None
    return round(float(hours) * float(conversion_factor), 4)


PROJECT_CATEGORIES = {worker_class.value for worker_class in WorkerClass} | {"Instalacja"}


def validate_project_category(category: str) -> str:
    normalized = str(category or "").strip()
    if normalized not in PROJECT_CATEGORIES:
        raise HTTPException(status_code=400, detail="Typ projektu musi odpowiadać jednej z klas pracowników")
    return normalized


def validate_deck_plan(target_m2: float, average_m2_per_hour: float):
    if target_m2 > 0 and average_m2_per_hour <= 0:
        raise HTTPException(status_code=400, detail="Dla celu m² podaj średnią m²/h większą od zera")

def deck_activity_names(payload):
    if payload.activities is not None:
        return list(dict.fromkeys(payload.activities))
    name = (payload.activity or "").strip()
    return [name] if name else []


def migrate_deck_targets_to_m2(db: Session):
    """Jednorazowo przenosi obowiązujące plany godzinowe bez zmiany historii wpisów."""
    migration_key = "deck_targets_m2_v2"
    if db.query(AppParameter).filter(AppParameter.key == migration_key).first():
        return
    for deck in db.query(ProjectDeck).all():
        if (deck.target_hours or 0) > 0 and (deck.conversion_factor or 0) > 0:
            deck.target_m2 = round(deck.target_hours * deck.conversion_factor, 4)
    db.add(AppParameter(key=migration_key, value=1.0))
    db.flush()


def sync_project_totals(db: Session, project: Project):
    """Sumuje niezależne plany pokładów; nigdy nie przelicza przydzielonych godzin z m²."""
    decks = db.query(ProjectDeck).filter(ProjectDeck.project_id == project.id).all()
    total_hours = 0.0
    total_m2 = 0.0
    for deck in decks:
        total_hours += float(deck.target_hours or 0)
        total_m2 += float(deck.target_m2 or 0)
    project.estimated_hours = round(total_hours, 4)
    project.total_m2 = round(total_m2, 4)

def generate_excel_bytes(db: Session, start_date=None, end_date=None, project_id: Optional[int] = None):
    query = db.query(TimeEntry).order_by(TimeEntry.date_created.desc())
    if project_id is not None:
        query = query.filter(TimeEntry.project_id == project_id)
    
    if start_date:
        if isinstance(start_date, str): start_date = datetime.strptime(start_date, "%Y-%m-%d")
        query = query.filter(TimeEntry.date_created >= start_date)
    if end_date:
        if isinstance(end_date, str): end_date = datetime.strptime(end_date, "%Y-%m-%d")
        query = query.filter(TimeEntry.date_created < (end_date + timedelta(days=1)))

    entries = query.all()
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Raport RCP"
    ws.append([
        "Data wpisu", "Kategoria pracownika", "Pracownik", "Kierownik",
        "Status", "Projekt", "Pokład", "Czynność", "Godziny",
        "Przelicznik (m²/godz.)", "Wyliczone m²", "Opis"
    ])

    total_hours = 0.0
    total_meters = 0.0
    for e in entries:
        worker_name = worker_display_name(e.worker) if e.worker else ""
        worker_class = e.worker.worker_class if e.worker else ""
        manager = e.recorded_by.email if e.recorded_by else ""
        status_txt = "Obecny" if e.is_present else "Nieobecny"
        project_name = e.project.name if e.project else ""
        deck_name = e.deck.name if e.deck else ""
        activity = e.deck.activity if e.deck else (e.position.name if e.position else "")
        factor = e.conversion_factor_used
        if factor is None and e.deck and e.deck.conversion_factor > 0:
            factor = e.deck.conversion_factor
        meters = e.meters_done if e.meters_done is not None else calculate_meters(e.hours, factor)
        if e.is_present:
            total_hours += float(e.hours or 0)
            total_meters += float(meters or 0)
        
        ws.append([
            e.date_created.strftime("%Y-%m-%d %H:%M"), excel_safe(worker_class),
            excel_safe(worker_name), excel_safe(manager), status_txt,
            excel_safe(project_name), excel_safe(deck_name), excel_safe(activity),
            e.hours if e.hours is not None else "", factor if factor is not None else "",
            round(meters, 2) if meters is not None else "", excel_safe(e.description)
        ])

    ws.append([])
    totals_row = ws.max_row + 1
    ws.cell(totals_row, 1, "SUMA")
    ws.cell(totals_row, 9, round(total_hours, 2))
    ws.cell(totals_row, 11, round(total_meters, 2))
    for cell in ws[totals_row]:
        cell.font = openpyxl.styles.Font(bold=True)

    stream = io.BytesIO()
    wb.save(stream)
    return stream.getvalue()

EMAIL_TIMEOUT_SECONDS = int(os.getenv("EMAIL_TIMEOUT_SECONDS", "20"))
RESEND_API_URL = "https://api.resend.com/emails"


class EmailDeliveryError(RuntimeError):
    """Czytelny błąd wysyłki, który można bezpiecznie pokazać administratorowi."""


def resolve_email_config(config: dict) -> dict:
    """Łączy ustawienia z panelu z opcjonalnymi, bezpieczniejszymi zmiennymi Railway."""
    provider = os.getenv("EMAIL_PROVIDER", str(config.get("provider") or "smtp")).strip().lower()
    resolved = {
        "provider": provider,
        "server": str(config.get("server") or "").strip(),
        "port": int(config.get("port") or 0),
        "email": str(config.get("email") or "").strip(),
        "password": str(config.get("password") or "").strip(),
    }

    if provider == "resend":
        resolved["email"] = os.getenv("EMAIL_FROM", resolved["email"]).strip()
        resolved["password"] = os.getenv("RESEND_API_KEY", resolved["password"]).strip()
        if not resolved["email"]:
            raise EmailDeliveryError("Podaj adres nadawcy zweryfikowany w Resend.")
        if not resolved["password"]:
            raise EmailDeliveryError("Podaj klucz API Resend lub ustaw RESEND_API_KEY w Railway.")
    elif provider == "smtp":
        resolved["server"] = os.getenv("SMTP_HOST", resolved["server"]).strip()
        resolved["port"] = int(os.getenv("SMTP_PORT", str(resolved["port"] or 587)))
        resolved["email"] = os.getenv("SMTP_USERNAME", resolved["email"]).strip()
        resolved["password"] = os.getenv("SMTP_PASSWORD", resolved["password"]).strip()
        if not resolved["server"] or not resolved["email"] or not resolved["password"]:
            raise EmailDeliveryError("Uzupełnij serwer SMTP, adres e-mail i hasło aplikacji.")
        if not 1 <= resolved["port"] <= 65535:
            raise EmailDeliveryError("Port SMTP musi być liczbą od 1 do 65535.")
        # Hasła aplikacji Google są często kopiowane w grupach rozdzielonych spacjami.
        if resolved["server"].lower() in {"smtp.gmail.com", "smtp.googlemail.com"}:
            resolved["password"] = resolved["password"].replace(" ", "")
    else:
        raise EmailDeliveryError("Nieobsługiwany dostawca e-mail. Wybierz Resend albo SMTP.")

    return resolved


def format_email_error(exc: Exception, provider: str) -> str:
    if isinstance(exc, EmailDeliveryError):
        return str(exc)
    if isinstance(exc, smtplib.SMTPAuthenticationError):
        server_message = exc.smtp_error.decode("utf-8", errors="replace") if isinstance(exc.smtp_error, bytes) else str(exc.smtp_error)
        return f"Serwer SMTP odrzucił logowanie ({exc.smtp_code}): {server_message}. Sprawdź login i hasło aplikacji."
    if isinstance(exc, (socket.timeout, TimeoutError)):
        return (
            "Przekroczono czas połączenia z serwerem SMTP. Na Railway Free, Trial i Hobby "
            "porty SMTP są zablokowane — wybierz Resend (HTTPS) albo plan Railway Pro i wykonaj redeploy."
        )
    if isinstance(exc, socket.gaierror):
        return "Nie udało się odnaleźć serwera pocztowego. Sprawdź nazwę hosta SMTP."
    if isinstance(exc, ssl.SSLError):
        return f"Błąd bezpiecznego połączenia TLS/SSL: {exc}"
    if isinstance(exc, smtplib.SMTPNotSupportedError):
        return "Serwer nie obsługuje wymaganego szyfrowania STARTTLS. Użyj portu 587 albo SSL na porcie 465."
    if isinstance(exc, urllib.error.HTTPError):
        try:
            response_body = exc.read().decode("utf-8", errors="replace")
            response_data = json.loads(response_body)
            detail = response_data.get("message") or response_data.get("error") or response_body
        except Exception:
            detail = str(exc.reason)
        return f"Resend odrzucił wysyłkę (HTTP {exc.code}): {detail}"
    if isinstance(exc, urllib.error.URLError):
        return f"Nie udało się połączyć z API Resend przez HTTPS: {exc.reason}"
    if isinstance(exc, (smtplib.SMTPException, OSError)):
        return f"Błąd połączenia z serwerem SMTP: {exc}"
    return f"Nie udało się wysłać wiadomości przez {provider}: {exc}"


def send_via_smtp(config: dict, to_email: str, subject: str, body: str,
                  attachment_filename: str = None, attachment_content: bytes = None):
    msg = EmailMessage()
    msg.set_content(body)
    msg["Subject"] = subject
    msg["From"] = f"Macholl RCP <{config['email']}>"
    msg["To"] = to_email
    if attachment_filename and attachment_content:
        msg.add_attachment(
            attachment_content,
            maintype="application",
            subtype="vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            filename=attachment_filename,
        )

    tls_context = ssl.create_default_context()
    if config["port"] == 465:
        with smtplib.SMTP_SSL(
            config["server"], config["port"], timeout=EMAIL_TIMEOUT_SECONDS, context=tls_context
        ) as smtp:
            smtp.ehlo()
            smtp.login(config["email"], config["password"])
            smtp.send_message(msg)
    else:
        with smtplib.SMTP(config["server"], config["port"], timeout=EMAIL_TIMEOUT_SECONDS) as smtp:
            smtp.ehlo()
            if not smtp.has_extn("starttls"):
                raise smtplib.SMTPNotSupportedError("STARTTLS unavailable")
            smtp.starttls(context=tls_context)
            smtp.ehlo()
            smtp.login(config["email"], config["password"])
            smtp.send_message(msg)


def send_via_resend(config: dict, to_email: str, subject: str, body: str,
                    attachment_filename: str = None, attachment_content: bytes = None):
    payload = {
        "from": f"Macholl RCP <{config['email']}>",
        "to": [to_email],
        "subject": subject,
        "text": body,
    }
    if attachment_filename and attachment_content:
        payload["attachments"] = [{
            "filename": attachment_filename,
            "content": base64.b64encode(attachment_content).decode("ascii"),
        }]

    request = urllib.request.Request(
        RESEND_API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {config['password']}",
            "Content-Type": "application/json",
            "User-Agent": "Macholl-RCP/1.0",
        },
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=EMAIL_TIMEOUT_SECONDS) as response:
        response.read()


def send_email_with_config(config: dict, to_email: str, subject: str, body: str,
                           attachment_filename: str = None, attachment_content: bytes = None):
    provider = str(config.get("provider") or "smtp").lower()
    try:
        resolved = resolve_email_config(config)
        provider = resolved["provider"]
        if provider == "resend":
            send_via_resend(resolved, to_email, subject, body, attachment_filename, attachment_content)
        else:
            send_via_smtp(resolved, to_email, subject, body, attachment_filename, attachment_content)
    except Exception as exc:
        raise EmailDeliveryError(format_email_error(exc, provider)) from exc


def send_email(to_email: str, subject: str, body: str,
               attachment_filename: str = None, attachment_content: bytes = None):
    db = SessionLocal()
    try:
        email_conf = db.query(SMTPConfig).first()
        if email_conf:
            config = {
                "provider": email_conf.provider or "smtp",
                "server": email_conf.server,
                "port": email_conf.port,
                "email": email_conf.email,
                "password": email_conf.password,
            }
        else:
            # Pozwala trzymać wszystkie dane dostępowe wyłącznie w Railway Variables.
            config = {"provider": "smtp", "server": "", "port": 587, "email": "", "password": ""}
    finally:
        db.close()

    try:
        send_email_with_config(config, to_email, subject, body, attachment_filename, attachment_content)
        logger.info("Wysłano e-mail do %s przez %s", to_email, config["provider"])
    except EmailDeliveryError as exc:
        logger.error("Nie udało się wysłać e-maila do %s: %s", to_email, exc)
        raise

def generate_random_password(length=12):
    return ''.join(secrets.choice(string.ascii_letters + string.digits + "!@#$%^&*") for _ in range(length))

def run_schema_migrations():
    """Małe, addytywne migracje dla instalacji utworzonych starszą wersją aplikacji."""
    db_inspector = inspect(engine)
    with engine.begin() as connection:
        user_columns = {column["name"] for column in db_inspector.get_columns("users")}
        if "allowed_worker_classes" not in user_columns:
            connection.execute(text("ALTER TABLE users ADD COLUMN allowed_worker_classes JSON"))
        worker_columns = {column["name"] for column in db_inspector.get_columns("workers")}
        if "worker_class" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN worker_class VARCHAR NOT NULL DEFAULT 'Inne'"))
        if "email" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN email VARCHAR"))
        if "user_id" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN user_id INTEGER"))
        if "can_report_hours" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN can_report_hours BOOLEAN NOT NULL DEFAULT FALSE"))
        if "is_deleted" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN is_deleted BOOLEAN NOT NULL DEFAULT FALSE"))
        if "deleted_at" not in worker_columns:
            connection.execute(text("ALTER TABLE workers ADD COLUMN deleted_at TIMESTAMP"))

        entry_columns = {column["name"] for column in db_inspector.get_columns("time_entries")}
        if "deck_id" not in entry_columns:
            connection.execute(text("ALTER TABLE time_entries ADD COLUMN deck_id INTEGER"))
        if "conversion_factor_used" not in entry_columns:
            connection.execute(text("ALTER TABLE time_entries ADD COLUMN conversion_factor_used FLOAT"))
        if "meters_done" not in entry_columns:
            connection.execute(text("ALTER TABLE time_entries ADD COLUMN meters_done FLOAT"))

        deck_columns = {column["name"] for column in db_inspector.get_columns("project_decks")}
        if "activities" not in deck_columns:
            connection.execute(text("ALTER TABLE project_decks ADD COLUMN activities JSON"))
        if "target_m2" not in deck_columns:
            connection.execute(text("ALTER TABLE project_decks ADD COLUMN target_m2 FLOAT NOT NULL DEFAULT 0"))
        if "target_hours" not in deck_columns:
            connection.execute(text("ALTER TABLE project_decks ADD COLUMN target_hours FLOAT NOT NULL DEFAULT 0"))

        smtp_columns = {column["name"] for column in db_inspector.get_columns("smtp_config")}
        if "provider" not in smtp_columns:
            connection.execute(text("ALTER TABLE smtp_config ADD COLUMN provider VARCHAR NOT NULL DEFAULT 'smtp'"))

        position_columns = {column["name"] for column in db_inspector.get_columns("job_positions")}
        if "is_active" not in position_columns:
            connection.execute(text("ALTER TABLE job_positions ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT TRUE"))

def link_user_to_worker(db: Session, user: User, worker_id: Optional[int]):
    """Łączy istniejące konto z pracownikiem; nigdy nie tworzy drugiego loginu."""
    old_worker = user.worker
    if old_worker and old_worker.is_deleted:
        raise HTTPException(status_code=400, detail="Konto usuniętego pracownika pozostaje zablokowane dla zachowania historii")
    worker = None
    if worker_id is not None:
        if user.role != RoleType.MANAGER:
            raise HTTPException(status_code=400, detail="Z pracownikiem można połączyć tylko konto kierownika/raportujące")
        worker = db.query(Worker).filter(Worker.id == worker_id, Worker.is_deleted.is_(False)).first()
        if not worker:
            raise HTTPException(status_code=404, detail="Nie znaleziono pracownika albo został usunięty")
        if worker.user_id is not None and worker.user_id != user.id:
            raise HTTPException(status_code=409, detail="Pracownik ma już przypisane konto")

    # Wszystkie warunki sprawdzamy przed zmianą istniejącego powiązania.
    if old_worker and old_worker != worker:
        old_worker.user = None
        old_worker.email = None
        old_worker.can_report_hours = False
    if worker:
        worker.user = user
        worker.email = user.email
        worker.can_report_hours = True
        user.is_active = bool(worker.is_active)

def initialize_database():
    Base.metadata.create_all(bind=engine)
    run_schema_migrations()
    db = SessionLocal()
    if not db.query(User).filter(User.email == "kh@orbis-software.pl").first():
        db.add(User(email="kh@orbis-software.pl", hashed_password=get_password_hash("Korneliusz358@@"), role=RoleType.ADMIN))
        db.commit()
    for project in db.query(Project).all():
        if not project.decks:
            deck = ProjectDeck(
                project_id=project.id,
                name="Ogólny",
                activity="Prace ogólne",
                conversion_factor=0.0,
                target_hours=float(project.estimated_hours or 0),
            )
            db.add(deck)
            db.flush()
            db.query(TimeEntry).filter(
                TimeEntry.project_id == project.id,
                TimeEntry.deck_id.is_(None),
            ).update({TimeEntry.deck_id: deck.id}, synchronize_session=False)
    db.flush()
    migrate_deck_targets_to_m2(db)
    for project in db.query(Project).all():
        sync_project_totals(db, project)
    for entry in db.query(TimeEntry).filter(TimeEntry.is_present.is_(True)).all():
        # Zachowujemy już zapisane wyniki historyczne; nowy wzór obowiązuje nowe wpisy.
        if entry.meters_done is None and entry.hours is not None and entry.deck:
            factor = float(entry.conversion_factor_used or entry.deck.conversion_factor or 0)
            entry.conversion_factor_used = factor if factor > 0 else None
            entry.meters_done = calculate_meters(entry.hours, factor)
    db.commit()
    db.close()

async def weekly_report_scheduler():
    """Automatyczna wysyłka raportu w niedzielę o 23:59 w skonfigurowanej strefie."""
    app_timezone = ZoneInfo(os.getenv("APP_TIMEZONE", "Europe/Warsaw"))
    while True:
        now = datetime.now(app_timezone)
        # Wylicz najbliższą niedzielę (6) o 23:59
        next_sunday = now + timedelta(days=(6 - now.weekday()) % 7)
        next_run = next_sunday.replace(hour=23, minute=59, second=0, microsecond=0)
        
        # Jeśli jest już niedziela po 23:59, przerzuć na kolejny tydzień
        if now >= next_run:
            next_run += timedelta(days=7)
            
        sleep_seconds = (next_run - now).total_seconds()
        print(f"[*] Harmonogram: Następny raport e-mail z plikiem Excel wygeneruje się: {next_run.strftime('%Y-%m-%d %H:%M')}")
        
        await asyncio.sleep(sleep_seconds)
        
        print("[*] Harmonogram: Rozpoczynam automatyczną wysyłkę raportu...")
        db = SessionLocal()
        try:
            subs = db.query(ReportSubscription).all()
            if subs:
                # Ostatni tydzień (Od poniedziałku do niedzieli włącznie)
                start_date = next_run.date() - timedelta(days=6)
                end_date = next_run.date()
                
                # Generowanie Excela w locie
                excel_bytes = generate_excel_bytes(db, start_date=start_date, end_date=end_date)
                filename = f"Raport_RCP_Tydzien_{start_date.strftime('%Y-%m-%d')}_do_{end_date.strftime('%Y-%m-%d')}.xlsx"
                
                body = f"Witaj,\n\nW załączniku przesyłamy automatyczny raport w formacie Excel z systemu Macholl RCP za ostatni tydzień ({start_date.strftime('%d.%m.%Y')} - {end_date.strftime('%d.%m.%Y')}).\n\nPozdrawiamy,\nSystem Macholl RCP"
                
                for sub in subs:
                    try:
                        await asyncio.to_thread(
                            send_email,
                            sub.email,
                            "Tygodniowy Raport Pracy - Macholl RCP",
                            body,
                            filename,
                            excel_bytes,
                        )
                    except EmailDeliveryError as exc:
                        # Błąd jednego adresu nie może zatrzymać wysyłki do pozostałych odbiorców.
                        logger.error("Raport dla %s nie został wysłany: %s", sub.email, exc)
        except Exception as e:
            print(f"[!] Błąd w trakcie automatycznej wysyłki: {e}")
        finally:
            db.close()

@asynccontextmanager
async def lifespan(app: FastAPI):
    initialize_database()
    task = asyncio.create_task(weekly_report_scheduler())
    yield
    task.cancel()

app = FastAPI(title="Macholl RCP", lifespan=lifespan)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

