# 5. ENDPOINTY API
# ==========================================
@app.post("/api/token")
def login(form_data: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(get_db)):
    user = db.query(User).filter(func.lower(User.email) == form_data.username.strip().lower()).first()
    if not user_can_login(user) or not verify_password(form_data.password, user.hashed_password):
        raise HTTPException(status_code=401, detail="Nieprawidłowy e-mail lub hasło")
    return {"access_token": create_access_token({"sub": user.email, "role": user.role}), "token_type": "bearer", "role": user.role, "permissions": {"workers": user.can_view_workers, "projects": user.can_view_projects, "analysis": user.can_view_analysis}}

@app.get("/api/users", response_model=List[UserResponse])
def get_users(db: Session = Depends(get_db), _: User = Depends(require_admin)): return db.query(User).all()

@app.post("/api/users")
def create_user(user: UserCreate, bt: BackgroundTasks, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    email = str(user.email).strip().lower()
    if db.query(User).filter(func.lower(User.email) == email).first(): raise HTTPException(400, "E-mail zajęty")
    rp = user.password or generate_random_password()
    if len(rp.encode("utf-8")) > 72:
        raise HTTPException(status_code=400, detail="Hasło może mieć maksymalnie 72 bajty UTF-8")
    account = User(email=email, hashed_password=get_password_hash(rp), role=user.role,
                   allowed_worker_classes=None if user.role == RoleType.ADMIN else normalize_allowed_worker_classes(user.allowed_worker_classes))
    db.add(account)
    db.flush()
    if user.worker_id is not None:
        link_user_to_worker(db, account, user.worker_id)
    db.commit()
    if user.password is None:
        bt.add_task(send_email, email, "Konto Macholl RCP", f"E-mail: {email}\nHasło: {rp}")
    return {"id": account.id, "message": "Konto utworzone i połączone z pracownikiem" if user.worker_id else "Konto utworzone"}

@app.put("/api/users/{user_id}/worker", response_model=UserResponse)
def update_user_worker(user_id: int, payload: UserWorkerLink, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    account = db.query(User).filter(User.id == user_id).first()
    if not account:
        raise HTTPException(status_code=404, detail="Nie znaleziono konta")
    link_user_to_worker(db, account, payload.worker_id)
    db.commit()
    db.refresh(account)
    return account

@app.put("/api/users/{user_id}/permissions")
def update_permissions(user_id: int, perms: UserPermissionsUpdate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    u = db.query(User).filter(User.id == user_id).first()
    if not u:
        raise HTTPException(status_code=404, detail="Nie znaleziono konta")
    for field in ("can_view_workers", "can_view_projects", "can_view_analysis"):
        value = getattr(perms, field)
        if value is not None:
            setattr(u, field, value)
    if "allowed_worker_classes" in perms.model_fields_set:
        u.allowed_worker_classes = None if u.role == RoleType.ADMIN else normalize_allowed_worker_classes(perms.allowed_worker_classes)
    db.commit()
    return {"message": "Zaktualizowano"}

@app.put("/api/users/{user_id}/password")
def update_user_password(user_id: int, payload: PasswordUpdate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    u = db.query(User).filter(User.id == user_id).first()
    if u:
        u.hashed_password = get_password_hash(payload.new_password)
        db.commit()
    return {"message": "Hasło zmienione"}

@app.delete("/api/users/{user_id}")
def delete_user(user_id: int, db: Session = Depends(get_db), current_user: User = Depends(require_admin)):
    if user_id == current_user.id:
        raise HTTPException(status_code=400, detail="Nie można wyłączyć własnego konta")
    u = db.query(User).filter(User.id == user_id).first()
    if u:
        u.is_active = False
        for worker in db.query(Worker).filter(Worker.user_id == u.id).all():
            worker.can_report_hours = False
        db.commit()
    return {"message": "Konto wyłączone. Historia wpisów i powiązanie z pracownikiem pozostały zachowane."}

@app.get("/api/workers", response_model=List[WorkerResponse])
def get_workers(include_deleted: bool = False, db: Session = Depends(get_db), current_user: User = Depends(get_current_user)):
    query = db.query(Worker).order_by(Worker.last_name, Worker.first_name)
    if not include_deleted or current_user.role != RoleType.ADMIN:
        query = query.filter(Worker.is_deleted.is_(False))
    if current_user.role == RoleType.MANAGER:
        query = query.filter(Worker.is_active.is_(True))
        if current_user.allowed_worker_classes is not None:
            query = query.filter(Worker.worker_class.in_(current_user.allowed_worker_classes))
    return query.all()

@app.post("/api/workers", response_model=WorkerResponse)
def add_worker(w: WorkerCreate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    first_name, last_name = w.first_name.strip(), w.last_name.strip()
    if not first_name or not last_name:
        raise HTTPException(status_code=400, detail="Podaj imię i nazwisko pracownika")
    email = str(w.email).strip().lower() if w.email else None
    if w.can_report_hours:
        if not email or not w.login_password:
            raise HTTPException(status_code=400, detail="Dla dostępu do raportów podaj e-mail i hasło startowe")
        if len(w.login_password.encode("utf-8")) > 72:
            raise HTTPException(status_code=400, detail="Hasło może mieć maksymalnie 72 bajty UTF-8")
        if db.query(User).filter(func.lower(User.email) == email).first():
            raise HTTPException(status_code=409, detail="Konto z tym e-mailem już istnieje. Dodaj pracownika bez nowego dostępu i przypisz istniejące konto w Kontach i uprawnieniach.")
    elif email or w.login_password:
        raise HTTPException(status_code=400, detail="Aby utworzyć konto, zaznacz dostęp do wpisywania raportów godzin")
    nw = Worker(
        first_name=first_name,
        last_name=last_name,
        worker_class=w.worker_class.value,
        is_active=w.is_active,
        can_report_hours=w.can_report_hours,
    )
    db.add(nw)
    if w.can_report_hours:
        account = User(email=email, hashed_password=get_password_hash(w.login_password), role=RoleType.MANAGER,
                       can_view_workers=True, can_view_projects=True, can_view_analysis=False)
        db.add(account)
        db.flush()
        link_user_to_worker(db, account, nw.id)
    # Pracownik i jego konto zapisują się razem; nie wysyłamy podanego hasła e-mailem.
    db.commit()
    db.refresh(nw)
    return nw

@app.put("/api/workers/{worker_id}", response_model=WorkerResponse)
def update_worker(worker_id: int, payload: WorkerUpdate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    worker = db.query(Worker).filter(Worker.id == worker_id, Worker.is_deleted.is_(False)).first()
    if not worker:
        raise HTTPException(status_code=404, detail="Nie znaleziono pracownika")
    if payload.first_name is not None:
        worker.first_name = payload.first_name.strip()
    if payload.last_name is not None:
        worker.last_name = payload.last_name.strip()
    if payload.worker_class is not None:
        worker.worker_class = payload.worker_class.value
    if payload.is_active is not None:
        worker.is_active = payload.is_active
    if payload.can_report_hours is not None:
        worker.can_report_hours = payload.can_report_hours
    if worker.user:
        worker.user.is_active = bool(worker.is_active and worker.can_report_hours)
    db.commit()
    db.refresh(worker)
    return worker

@app.delete("/api/workers/{worker_id}")
def delete_worker(worker_id: int, db: Session = Depends(get_db), current_user: User = Depends(require_admin)):
    worker = db.query(Worker).filter(Worker.id == worker_id).first()
    if not worker:
        raise HTTPException(status_code=404, detail="Nie znaleziono pracownika")
    if worker.user_id == current_user.id:
        raise HTTPException(status_code=400, detail="Nie można usunąć pracownika powiązanego z własnym kontem administratora")
    worker.is_deleted = True
    worker.deleted_at = worker.deleted_at or datetime.now(timezone.utc).replace(tzinfo=None)
    worker.is_active = False
    worker.can_report_hours = False
    if worker.user:
        worker.user.is_active = False
    # Nie usuwamy rekordu ani relacji: nazwisko, raporty i wszystkie godziny pozostają.
    db.commit()
    return {"message": "Pracownik usunięty z listy. Wszystkie dane i godziny pozostały w historii."}

@app.get("/api/projects", response_model=List[ProjectResponse])
def get_projects(db: Session = Depends(get_db), _: User = Depends(get_current_user)): return db.query(Project).all()

@app.post("/api/projects", response_model=ProjectResponse)
def add_project(p: ProjectCreate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    for deck in p.decks:
        validate_deck_plan(deck.target_m2, deck.conversion_factor)
    project = Project(
        name=p.name.strip(),
        category=validate_project_category(p.category),
        estimated_hours=p.estimated_hours,
    )
    db.add(project)
    db.flush()
    decks = p.decks or [DeckCreate(name="Ogólny", activity="Prace ogólne", target_hours=p.estimated_hours)]
    for deck in decks:
        db.add(ProjectDeck(
            project_id=project.id,
            name=deck.name.strip(),
            activities=deck_activity_names(deck),
            conversion_factor=deck.conversion_factor,
            target_m2=deck.target_m2,
            target_hours=deck.target_hours,
        ))
    db.flush()
    sync_project_totals(db, project)
    db.commit()
    db.refresh(project)
    return project

@app.post("/api/projects/{project_id}/decks", response_model=DeckResponse)
def add_project_deck(project_id: int, payload: DeckCreate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    validate_deck_plan(payload.target_m2, payload.conversion_factor)
    project = db.query(Project).filter(Project.id == project_id).first()
    if not project:
        raise HTTPException(status_code=404, detail="Nie znaleziono projektu")
    deck = ProjectDeck(
        project_id=project_id,
        name=payload.name.strip(),
        activities=deck_activity_names(payload),
        conversion_factor=payload.conversion_factor,
        target_m2=payload.target_m2,
        target_hours=payload.target_hours,
    )
    db.add(deck)
    db.flush()
    sync_project_totals(db, project)
    db.commit()
    db.refresh(deck)
    return deck


@app.put("/api/projects/{project_id}", response_model=ProjectResponse)
def update_project(project_id: int, payload: ProjectUpdate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    project = db.query(Project).filter(Project.id == project_id).first()
    if not project:
        raise HTTPException(status_code=404, detail="Nie znaleziono projektu")
    if payload.name is not None:
        project.name = payload.name.strip()
    if payload.category is not None:
        project.category = validate_project_category(payload.category)
    db.commit()
    db.refresh(project)
    return project


@app.put("/api/projects/{project_id}/decks/{deck_id}", response_model=DeckResponse)
def update_project_deck(project_id: int, deck_id: int, payload: DeckUpdate,
                        db: Session = Depends(get_db), _: User = Depends(require_admin)):
    project = db.query(Project).filter(Project.id == project_id).first()
    if not project:
        raise HTTPException(status_code=404, detail="Nie znaleziono projektu")
    deck = db.query(ProjectDeck).filter(
        ProjectDeck.id == deck_id,
        ProjectDeck.project_id == project_id,
    ).first()
    if not deck:
        raise HTTPException(status_code=404, detail="Nie znaleziono pokładu w tym projekcie")

    target_m2 = payload.target_m2 if payload.target_m2 is not None else deck.target_m2
    average = payload.conversion_factor if payload.conversion_factor is not None else deck.conversion_factor
    validate_deck_plan(target_m2, average)

    if payload.name is not None:
        deck.name = payload.name.strip()
    if "activities" in payload.model_fields_set or "activity" in payload.model_fields_set:
        deck.activities = deck_activity_names(payload)
    if payload.conversion_factor is not None:
        deck.conversion_factor = payload.conversion_factor
    deck.target_m2 = target_m2
    if payload.target_hours is not None:
        deck.target_hours = payload.target_hours
    if payload.is_active is not None:
        deck.is_active = payload.is_active

    db.flush()
    sync_project_totals(db, project)
    db.commit()
    db.refresh(deck)
    return deck

@app.get("/api/positions", response_model=List[PositionResponse])
def get_positions(db: Session = Depends(get_db), _: User = Depends(get_current_user)):
    return db.query(JobPosition).filter(JobPosition.is_active.is_(True)).order_by(JobPosition.name).all()

@app.post("/api/positions", response_model=PositionResponse)
def add_position(pos: PositionCreate, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    name = pos.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail="Wpisz nazwę czynności")
    existing = db.query(JobPosition).filter(func.lower(JobPosition.name) == name.lower()).first()
    if existing and existing.is_active:
        raise HTTPException(status_code=400, detail="Taka czynność już istnieje")
    if existing:
        existing.is_active = True
        db.commit()
        db.refresh(existing)
        return existing
    np = JobPosition(name=name)
    db.add(np)
    db.commit()
    db.refresh(np)
    return np

@app.delete("/api/positions/{position_id}")
def delete_position(position_id: int, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    position = db.get(JobPosition, position_id)
    if not position:
        raise HTTPException(status_code=404, detail="Nie znaleziono czynności")
    # Remove only the choice from the catalog; retain legacy FKs and saved deck names.
    position.is_active = False
    db.commit()
    return {"message": "Czynność usunięta z listy. Zapisane pokłady i raporty pozostają bez zmian."}

@app.post("/api/entries/batch")
def add_entries_batch(payload: BatchTimeEntryCreate, db: Session = Depends(get_db), current_user: User = Depends(require_manager)):
    if not payload.entries:
        raise HTTPException(status_code=400, detail="Lista wpisów jest pusta")
    for e in payload.entries:
        worker = db.query(Worker).filter(
            Worker.id == e.worker_id, Worker.is_active.is_(True), Worker.is_deleted.is_(False)
        ).first()
        if not worker:
            raise HTTPException(status_code=400, detail=f"Pracownik {e.worker_id} nie istnieje lub jest nieaktywny")
        if not can_report_worker_class(current_user, worker):
            raise HTTPException(status_code=403, detail="To konto nie ma uprawnień do raportowania wybranej klasy pracowników")

        if not e.is_present:
            raise HTTPException(status_code=400, detail="Nieobecność wynika z braku wpisu RCP i nie jest zapisywana ręcznie")
        if e.hours is None:
            raise HTTPException(status_code=400, detail="Wpisz liczbę godzin")

        is_fiber_optics = worker.worker_class == WorkerClass.FIBER_OPTICS.value
        if is_fiber_optics:
            if e.position_id is None:
                raise HTTPException(status_code=400, detail="Dla klasy Światłowody wybierz czynność")
            position = db.query(JobPosition).filter(
                JobPosition.id == e.position_id,
                JobPosition.is_active.is_(True),
            ).first()
            if not position:
                raise HTTPException(status_code=400, detail="Wybrana czynność nie istnieje lub jest nieaktywna")
            project_id = None
            deck_id = None
            deck = None
        else:
            if e.project_id is None or e.deck_id is None:
                raise HTTPException(status_code=400, detail="Wybierz projekt i pokład")
            deck = db.query(ProjectDeck).filter(
                ProjectDeck.id == e.deck_id,
                ProjectDeck.project_id == e.project_id,
                ProjectDeck.is_active.is_(True),
            ).first()
            if not deck:
                raise HTTPException(status_code=400, detail="Wybrany pokład nie należy do projektu lub jest nieaktywny")
            project_id = e.project_id
            deck_id = e.deck_id

        ne = TimeEntry(
            worker_id=e.worker_id,
            project_id=project_id,
            deck_id=deck_id,
            position_id=e.position_id,
            is_present=True,
            absence_reason=None,
            hours=e.hours,
            conversion_factor_used=deck.conversion_factor if deck and deck.conversion_factor > 0 else None,
            meters_done=calculate_meters(e.hours, deck.conversion_factor) if deck else None,
            description=e.description,
            recorded_by_id=current_user.id
        )
        db.add(ne)
    db.commit()
    return {"message": "Zapisano koszyk RCP"}

@app.get("/api/workers-presence/today")
def get_workers_presence_today(db: Session = Depends(get_db), _: User = Depends(get_current_user)):
    local_now = datetime.now().astimezone()
    local_today_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    today_start = local_today_start.astimezone(timezone.utc).replace(tzinfo=None)
    tomorrow_start = (local_today_start + timedelta(days=1)).astimezone(timezone.utc).replace(tzinfo=None)
    rows = db.query(TimeEntry.worker_id).filter(
        TimeEntry.is_present.is_(True),
        TimeEntry.date_created >= today_start,
        TimeEntry.date_created < tomorrow_start,
    ).distinct().all()
    return {"present_worker_ids": [worker_id for (worker_id,) in rows]}

@app.get("/api/entries")
def get_entries(start: str = None, end: str = None, db: Session = Depends(get_db), current_user: User = Depends(get_current_user)):
    query = db.query(TimeEntry)
    if current_user.role == RoleType.MANAGER:
        query = query.filter(TimeEntry.recorded_by_id == current_user.id)
    try:
        if start:
            query = query.filter(TimeEntry.date_created >= datetime.strptime(start, "%Y-%m-%d"))
        if end:
            query = query.filter(TimeEntry.date_created < datetime.strptime(end, "%Y-%m-%d") + timedelta(days=1))
    except ValueError:
        raise HTTPException(status_code=400, detail="Nieprawidłowy format daty; użyj RRRR-MM-DD")
    entries = query.order_by(TimeEntry.date_created.desc()).all()
    res = []
    for e in entries:
        factor = e.conversion_factor_used
        if factor is None and e.deck and e.deck.conversion_factor > 0:
            factor = e.deck.conversion_factor
        meters = e.meters_done if e.meters_done is not None else calculate_meters(e.hours, factor)
        res.append({
            "id": e.id,
            "date": e.date_created.strftime("%Y-%m-%d %H:%M"),
            "raw_date": e.date_created.isoformat(),
            "worker_id": e.worker_id,
            "worker": worker_display_name(e.worker) if e.worker else "Brak",
            "worker_deleted": bool(e.worker and e.worker.is_deleted),
            "worker_class": e.worker.worker_class if e.worker else WorkerClass.OTHER.value,
            "manager": e.recorded_by.email if e.recorded_by else "Brak",
            "project_id": e.project_id,
            "project_name": e.project.name if e.project else "-",
            "project_category": e.project.category if e.project else "-",
            "deck_id": e.deck_id,
            "deck_name": e.deck.name if e.deck else "-",
            "activity": e.deck.activity if e.deck else (e.position.name if e.position else "-"),
            "position": e.position.name if e.position else "-",
            "is_present": e.is_present,
            "hours": e.hours,
            "conversion_factor": factor,
            "meters": round(meters, 2) if meters is not None else None,
            "desc": e.description,
        })
    return res

@app.get("/api/reports/export")
def export_excel(start: str = None, end: str = None, project_id: Optional[int] = None,
                 db: Session = Depends(get_db), _: User = Depends(require_admin)):
    try:
        if project_id is not None and not db.get(Project, project_id):
            raise HTTPException(status_code=404, detail="Nie znaleziono projektu")
        excel_bytes = generate_excel_bytes(db, start, end, project_id=project_id)
    except ValueError:
        raise HTTPException(status_code=400, detail="Nieprawidłowy format daty; użyj RRRR-MM-DD")
    stream = io.BytesIO(excel_bytes)
    return StreamingResponse(stream, media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers={"Content-Disposition": "attachment; filename=raport_rcp.xlsx"})

@app.get("/api/summary/monthly")
def monthly_summary(month: str, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    try:
        start_date = datetime.strptime(f"{month}-01", "%Y-%m-%d")
    except ValueError:
        raise HTTPException(status_code=400, detail="Nieprawidłowy miesiąc; użyj RRRR-MM")
    next_month = (start_date.replace(day=28) + timedelta(days=4)).replace(day=1)
    entries = db.query(TimeEntry).filter(
        TimeEntry.date_created >= start_date,
        TimeEntry.date_created < next_month,
        TimeEntry.is_present.is_(True),
    ).all()

    categories = {}
    total_hours = 0.0
    for entry in entries:
        if not entry.worker or entry.hours is None:
            continue
        hours = float(entry.hours)
        total_hours += hours
        class_name = entry.worker.worker_class or WorkerClass.OTHER.value
        category = categories.setdefault(class_name, {"name": class_name, "total_hours": 0.0, "workers": {}})
        category["total_hours"] += hours
        worker = category["workers"].setdefault(entry.worker_id, {
            "worker_id": entry.worker_id,
            "worker": worker_display_name(entry.worker),
            "worker_deleted": bool(entry.worker.is_deleted),
            "total_hours": 0.0,
            "projects": {},
        })
        worker["total_hours"] += hours
        project_key = entry.project_id or 0
        project = worker["projects"].setdefault(project_key, {
            "project": entry.project.name if entry.project else "Bez projektu",
            "total_hours": 0.0,
            "decks": {},
        })
        project["total_hours"] += hours
        deck_key = entry.deck_id or 0
        deck = project["decks"].setdefault(deck_key, {
            "deck": entry.deck.name if entry.deck else "Bez pokładu",
            "activity": entry.deck.activity if entry.deck else (entry.position.name if entry.position else "-"),
            "hours": 0.0,
        })
        deck["hours"] += hours

    category_list = []
    for category in categories.values():
        worker_list = []
        for worker in category["workers"].values():
            project_list = []
            for project in worker["projects"].values():
                project["total_hours"] = round(project["total_hours"], 2)
                project["decks"] = [
                    {**deck, "hours": round(deck["hours"], 2)}
                    for deck in project["decks"].values()
                ]
                project_list.append(project)
            worker["total_hours"] = round(worker["total_hours"], 2)
            worker["projects"] = project_list
            worker_list.append(worker)
        category["total_hours"] = round(category["total_hours"], 2)
        category["workers"] = worker_list
        category_list.append(category)

    return {"month": month, "total_hours": round(total_hours, 2), "categories": category_list}

