@app.get("/api/smtp-config")
def get_smtp_config(db: Session = Depends(get_db), _: User = Depends(require_admin)):
    conf = db.query(SMTPConfig).first()
    if not conf:
        provider = os.getenv("EMAIL_PROVIDER", "resend").strip().lower()
        env_secret = os.getenv("RESEND_API_KEY" if provider == "resend" else "SMTP_PASSWORD", "")
        return {
            "provider": provider,
            "server": os.getenv("SMTP_HOST", "smtp.gmail.com"),
            "port": int(os.getenv("SMTP_PORT", "587")),
            "email": os.getenv("EMAIL_FROM" if provider == "resend" else "SMTP_USERNAME", ""),
            "password": "",
            "has_password": bool(env_secret),
        }
    provider = conf.provider or "smtp"
    env_secret = os.getenv("RESEND_API_KEY" if provider == "resend" else "SMTP_PASSWORD", "")
    return {
        "provider": provider,
        "server": conf.server,
        "port": conf.port,
        "email": conf.email,
        # Sekret nie powinien wracać do przeglądarki po każdym odświeżeniu panelu.
        "password": "",
        "has_password": bool(conf.password or env_secret),
    }

@app.put("/api/smtp-config")
def update_smtp_config(payload: SMTPConfigModel, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    provider = payload.provider.strip().lower()
    if provider not in {"smtp", "resend"}:
        raise HTTPException(status_code=400, detail="Wybierz dostawcę Resend albo SMTP")
    conf = db.query(SMTPConfig).first()
    if conf:
        previous_provider = conf.provider or "smtp"
        conf.provider = provider
        conf.server = payload.server.strip()
        conf.port = payload.port
        conf.email = str(payload.email).strip()
        if payload.password.strip():
            conf.password = payload.password.strip()
        elif previous_provider != provider:
            conf.password = ""
    else:
        db.add(SMTPConfig(
            provider=provider,
            server=payload.server.strip(),
            port=payload.port,
            email=str(payload.email).strip(),
            password=payload.password.strip(),
        ))
    db.commit()
    env_secret = os.getenv("RESEND_API_KEY" if provider == "resend" else "SMTP_PASSWORD", "")
    return {
        "message": "Ustawienia zapisane",
        "has_password": bool(payload.password.strip() or (conf and conf.password) or env_secret),
    }

@app.post("/api/smtp-config/test")
def test_smtp_config(payload: SMTPConfigModel, db: Session = Depends(get_db), _: User = Depends(require_admin)):
    try:
        config = payload.model_dump()
        config["email"] = str(payload.email)
        if not config["password"]:
            saved_config = db.query(SMTPConfig).first()
            if saved_config and (saved_config.provider or "smtp") == payload.provider.strip().lower():
                config["password"] = saved_config.password
        send_email_with_config(
            config,
            str(payload.email),
            "Test wysyłki — Macholl RCP",
            "To jest wiadomość testowa. Konfiguracja wysyłki e-mail w Macholl RCP działa poprawnie.",
        )
        provider_name = "Resend (HTTPS)" if payload.provider.lower() == "resend" else "SMTP"
        return {"message": f"Wiadomość testowa została wysłana przez {provider_name}. Sprawdź skrzynkę i spam."}
    except EmailDeliveryError as exc:
        logger.warning("Test konfiguracji e-mail nie powiódł się: %s", exc)
        raise HTTPException(status_code=400, detail=str(exc)) from exc

